 def forward(self,x): return x+self.pe[:,:x.size(1)]
class M(nn.Module):
 def __init__(self):
  super().__init__(); self.embedding=nn.Linear(64,128);self.pos_encoder=PE();self.transformer_encoder=nn.TransformerEncoder(nn.TransformerEncoderLayer(128,8,256,0.1,batch_first=True),3);self.transformer_decoder=nn.TransformerDecoder(nn.TransformerDecoderLayer(128,8,256,0.1,batch_first=True),1);self.output_layer=nn.Linear(128,64)
